"""Copy every payout from the Tallyline Payouts API into payouts.jsonl."""
import argparse
import email.utils
import json
import os
import tempfile
import time
import urllib.error
import urllib.parse
import urllib.request


def _retry_after_seconds(value):
    try:
        return max(0.0, float(value))
    except (TypeError, ValueError):
        pass
    try:
        when = email.utils.parsedate_to_datetime(value)
    except (TypeError, ValueError):
        return 1.0
    return max(0.0, when.timestamp() - time.time())


def _get_window(url):
    """GET one window, retrying the identical request while rate limited."""
    while True:
        try:
            with urllib.request.urlopen(url, timeout=30) as resp:
                return json.load(resp)
        except urllib.error.HTTPError as exc:
            if exc.code != 429:
                raise
            delay = _retry_after_seconds(exc.headers.get("Retry-After"))
            time.sleep(delay)


def _is_invalid_cursor(exc):
    if exc.code != 400:
        return False
    try:
        return json.load(exc) == {"error": "invalid_cursor"}
    except (ValueError, TypeError):
        return False


def fetch_payouts(base_url, limit=None):
    """Yield each payout exactly once, following v2 export windows."""
    seen = set()
    cursor = None
    restarted = False
    while True:
        query = {}
        if cursor is not None:
            query["cursor"] = cursor
        if limit is not None:
            query["limit"] = limit
        url = f"{base_url}/v2/payouts"
        if query:
            url += "?" + urllib.parse.urlencode(query)

        try:
            data = _get_window(url)
        except urllib.error.HTTPError as exc:
            if _is_invalid_cursor(exc) and not restarted:
                # The cursor expired: start the export again from the beginning.
                # Already-yielded ids are still in `seen`, so nothing is duplicated.
                restarted = True
                cursor = None
                continue
            raise

        for payout in data["payouts"]:
            if payout["id"] not in seen:
                seen.add(payout["id"])
                yield payout

        if data["drained"]:
            return
        cursor = data["cursor"]


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--base-url", required=True)
    ap.add_argument("--out", default="payouts.jsonl")
    args = ap.parse_args()

    base_url = args.base_url.rstrip("/")
    out_dir = os.path.dirname(os.path.abspath(args.out))
    fd, tmp_path = tempfile.mkstemp(dir=out_dir, prefix=".payouts-", suffix=".jsonl")
    count = 0
    try:
        with os.fdopen(fd, "w") as f:
            for payout in fetch_payouts(base_url):
                f.write(json.dumps(payout) + "\n")
                count += 1
        os.replace(tmp_path, args.out)
    except BaseException:
        try:
            os.unlink(tmp_path)
        except FileNotFoundError:
            pass
        raise
    print(f"synced {count} payouts")


if __name__ == "__main__":
    main()

